"""
Language character sets — which codepoints an orthography needs.

Answers "what does Turkish need?" rather than "what is in this Unicode block",
so glyphs can be created per language instead of per range. Data is bundled as
data/language_charsets.json and generated by scripts/gen_language_charsets.py
from googlefonts/lang; nothing here imports anything outside the standard
library, which keeps this module in the consumer tier.

Copyright 2026 Alexander Lubovenko
Licensed under the Apache License, Version 2.0
"""

import json
import logging
import unicodedata
from dataclasses import dataclass, field
from functools import lru_cache
from pathlib import Path

logger = logging.getLogger(__name__)

_DATA_PATH = Path(__file__).parent / "language_charsets.json"

# Schema version this module knows how to read.
_DATA_VERSION = 1

# Selectable character levels, in the order a UI should offer them.
LEVELS = ("base", "auxiliary", "marks", "punctuation", "numerals")

# What a plain "add this language" means: the letters of the orthography.
# Capitals are already part of `base` — the generator derives them, because the
# source data lists lowercase only for many bicameral languages.
DEFAULT_LEVELS = ("base",)


@dataclass(frozen=True)
class LanguageEntry:
    """One language/script orthography and the characters it uses."""

    id: str  # "ru_Cyrl"
    name: str  # "Russian"
    autonym: str  # "Русский"
    script: str  # "Cyrl"
    script_name: str  # "Cyrillic"
    population: int
    historical: bool
    regions: tuple[str, ...]  # ("Asia", "Europe")

    base: str
    auxiliary: str
    marks: str
    punctuation: str
    numerals: str

    # Where the letters come from: "gflanguages", or "font-rover" for the
    # languages scripts/language_extras.json adds or completes.
    source: str = "gflanguages"

    def codepoints(self, levels=DEFAULT_LEVELS) -> set[int]:
        """Return the codepoints of the requested levels.

        Args:
            levels: Any subset of LEVELS.

        Raises:
            ValueError: If a level is not one of LEVELS.
        """
        result: set[int] = set()
        for level in levels:
            if level not in LEVELS:
                raise ValueError(f"Unknown level: {level!r} (expected one of {LEVELS})")
            result.update(ord(char) for char in getattr(self, level))
        return result


@dataclass(frozen=True)
class ScriptGroup:
    """All languages written in one script, for a two-level picker.

    ``by_region`` splits the languages by region group (Europe, Africa, …). A
    language appears under every region group it is spoken in rather than one
    "primary" group — Turkish is listed under both Europe and Asia, which is
    where users will look for it.
    """

    id: str  # "Latn"
    name: str  # "Latin"
    family: str  # "European"
    languages: tuple[LanguageEntry, ...]
    by_region: dict[str, tuple[LanguageEntry, ...]] = field(default_factory=dict)


@dataclass(frozen=True)
class Coverage:
    """How much of a language a font already supports."""

    total: int
    covered: int
    missing: tuple[int, ...]

    @property
    def ratio(self) -> float:
        """Covered share in 0.0–1.0 (1.0 when the language needs nothing)."""
        return self.covered / self.total if self.total else 1.0


# Below this many languages a script needs no region sub-grouping: only Latin
# (892 languages) is unwieldy flat, Cyrillic (77) and the rest are not.
_REGION_SPLIT_THRESHOLD = 100


@lru_cache(maxsize=1)
def _load() -> tuple[LanguageEntry, ...]:
    """Read and parse the bundled data file (cached).

    A missing or broken file degrades to an empty list with a logged error: the
    language picker then shows nothing instead of taking the application down.
    """
    try:
        with open(_DATA_PATH, encoding="utf-8") as f:
            payload = json.load(f)
    except Exception as e:  # noqa: BLE001 - broken bundled data must not be fatal
        logger.error(f"Failed to load language charsets from {_DATA_PATH}: {e}")
        return ()

    version = payload.get("version")
    if version != _DATA_VERSION:
        logger.error(
            f"Unsupported language charset data version {version} "
            f"(expected {_DATA_VERSION}) in {_DATA_PATH}"
        )
        return ()

    scripts = payload.get("scripts", {})
    entries = [
        LanguageEntry(
            id=row["id"],
            name=row["name"],
            autonym=row["autonym"],
            script=row["script"],
            script_name=scripts.get(row["script"], {}).get("name", row["script"]),
            population=row["pop"],
            historical=row["hist"],
            regions=tuple(row["regions"]),
            base=row["base"],
            auxiliary=row["aux"],
            marks=row["marks"],
            punctuation=row["punct"],
            numerals=row["num"],
            source=row.get("src", "gflanguages"),
        )
        for row in payload.get("languages", ())
    ]

    # Most-spoken first inside each script — otherwise English and German sink
    # into an alphabetical list of 892 Latin-script languages.
    entries.sort(key=lambda e: (e.script_name, -e.population, e.name))
    return tuple(entries)


def get_languages() -> tuple[LanguageEntry, ...]:
    """Return every known language, grouped by script and most-spoken first."""
    return _load()


def get_language(lang_id: str) -> LanguageEntry | None:
    """Return the language with this id ("ru_Cyrl"), or None."""
    return _by_id().get(lang_id)


@lru_cache(maxsize=1)
def _by_id() -> dict[str, LanguageEntry]:
    return {entry.id: entry for entry in _load()}


def codepoints_for(lang_ids, levels=DEFAULT_LEVELS) -> set[int]:
    """Return the union of codepoints needed by several languages.

    Unknown ids are ignored, so a stale selection cannot break glyph creation.
    """
    result: set[int] = set()
    for lang_id in lang_ids:
        entry = get_language(lang_id)
        if entry is not None:
            result |= entry.codepoints(levels)
    return result


@lru_cache(maxsize=1)
def get_script_tree() -> tuple[ScriptGroup, ...]:
    """Return languages grouped by script, largest script first.

    Scripts with many languages also get ``by_region`` filled in; see
    ScriptGroup.
    """
    grouped: dict[str, list[LanguageEntry]] = {}
    for entry in _load():
        grouped.setdefault(entry.script, []).append(entry)

    groups = []
    for script_id, entries in grouped.items():
        by_region: dict[str, tuple[LanguageEntry, ...]] = {}
        if len(entries) >= _REGION_SPLIT_THRESHOLD:
            regions: dict[str, list[LanguageEntry]] = {}
            for entry in entries:
                for region in entry.regions or ("Other",):
                    regions.setdefault(region, []).append(entry)
            by_region = {name: tuple(v) for name, v in sorted(regions.items())}

        groups.append(
            ScriptGroup(
                id=script_id,
                name=entries[0].script_name,
                family=_script_family(script_id),
                languages=tuple(entries),
                by_region=by_region,
            )
        )

    groups.sort(key=lambda g: (-len(g.languages), g.name))
    return tuple(groups)


@lru_cache(maxsize=1)
def _script_families() -> dict[str, str]:
    """Script id -> family ("European", "Indic", …), from the data file."""
    try:
        with open(_DATA_PATH, encoding="utf-8") as f:
            scripts = json.load(f).get("scripts", {})
    except Exception:  # noqa: BLE001 - already reported by _load()
        return {}
    return {sid: info.get("family", "") for sid, info in scripts.items()}


def _script_family(script_id: str) -> str:
    return _script_families().get(script_id, "")


def _fold(text: str) -> str:
    """Casefold and strip diacritics, so "Kazakh" matches "kazakh"."""
    decomposed = unicodedata.normalize("NFD", text.casefold())
    return "".join(c for c in decomposed if unicodedata.category(c) != "Mn")


def search_languages(query: str) -> tuple[LanguageEntry, ...]:
    """Find languages by id, language code, English name or autonym.

    Matching is a case- and diacritic-insensitive substring test, so "kaz",
    "Kazakh" and "Қазақ" all find kk_Cyrl. An empty query returns everything.
    """
    needle = _fold(query.strip())
    if not needle:
        return _load()

    return tuple(
        entry
        for entry in _load()
        if needle in _fold(entry.id)
        or needle in _fold(entry.name)
        or needle in _fold(entry.autonym)
    )


def language_coverage(codepoints, lang_id: str, levels=DEFAULT_LEVELS) -> Coverage:
    """Report how much of a language the given codepoints already cover.

    Args:
        codepoints: What the font has — e.g. ``set(font.getCharacterMapping())``.
        lang_id: Language id, as in LanguageEntry.id.
        levels: Which character levels to require.

    Returns:
        Coverage; an unknown language id yields an empty, fully covered result.
    """
    entry = get_language(lang_id)
    if entry is None:
        return Coverage(total=0, covered=0, missing=())

    required = entry.codepoints(levels)
    have = set(codepoints)
    missing = required - have
    return Coverage(
        total=len(required),
        covered=len(required) - len(missing),
        missing=tuple(sorted(missing)),
    )
